-- +goose Up
-- A file an operator uploaded for an outbound email. Only this row lets its author
-- attach the file, once and before it expires; knowing the reference is not enough.
-- The file itself stays in storage, which may remove it by its own retention.
CREATE TABLE email.attachment_upload (
    domain_id          bigint NOT NULL,
    -- Generated by the service; also the uuid of the file in storage.
    reference          uuid NOT NULL,
    author_user_id     bigint NOT NULL,
    file_id            bigint NOT NULL,
    file_name          text NOT NULL,
    mime_type          text NOT NULL,
    size               bigint NOT NULL,
    expires_at         timestamptz NOT NULL,
    -- Set by Send when the file is attached; the expiry no longer applies then.
    used_by_message_id bigint NULL,
    created_at         timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT attachment_upload_pkey
        PRIMARY KEY (domain_id, reference),
    CONSTRAINT attachment_upload_message_fk
        FOREIGN KEY (domain_id, used_by_message_id)
        REFERENCES email.message (domain_id, id)
        ON DELETE CASCADE,
    -- Every column here is NOT NULL, so no term can be NULL.
    CONSTRAINT attachment_upload_values_valid
        CHECK (
            domain_id > 0 AND author_user_id > 0 AND file_id > 0 AND size > 0
            AND file_name <> '' AND mime_type <> ''
        )
);

-- Cleanup of expired uploads that were never attached.
CREATE INDEX attachment_upload_unused_expires_idx
    ON email.attachment_upload (expires_at)
    WHERE used_by_message_id IS NULL;

-- +goose Down
-- The first Down of a full rollback refuses while outbound emails exist, before
-- anything is dropped (00016 drops their data). Writes stay stopped for the whole
-- rollback: the lock lasts one migration.
-- +goose StatementBegin
DO $$
BEGIN
    LOCK TABLE email.message IN SHARE MODE;
    IF EXISTS (SELECT 1 FROM email.message WHERE direction = 'outbound') THEN
        RAISE EXCEPTION 'outbound emails exist: rolling back would lose their authors, delivery and request ids';
    END IF;
END $$;
-- +goose StatementEnd

DROP TABLE IF EXISTS email.attachment_upload;
